def _monomials(x, degree):
    from itertools import combinations_with_replacement
    return np.column_stack([np.prod(x[:, cols], axis=1) for cols in combinations_with_replacement(range(x.shape[1]), degree)])

def _matern_readout(x, xt, p, pt, y):
    from scipy.linalg import cho_factor
    from scipy.linalg import cho_solve
    from scipy.optimize import minimize
    from scipy.linalg import qr
    n = qr(p, mode='full')[0][:, p.shape[1]:]
    v = n.T @ y
    delta = (x[:, None] - x[None, :]) ** 2
    delta_test = (xt[:, None] - x[None, :]) ** 2

    def kernel(distance_sq, par):
        r2 = distance_sq @ np.exp(par[:x.shape[1]])
        r = np.sqrt(r2)
        return (1 + r + 0.4 * r2 + r2 * r / 15) * np.exp(-r)

    def objective(par):
        k = n.T @ kernel(delta, par) @ n + np.exp(par[-1]) * np.eye(len(v))
        f = cho_factor(k)
        return np.log(v @ cho_solve(f, v) / len(v)) + 2 * np.log(np.diag(f[0])).mean()
    par = minimize(objective, np.log([0.24] * x.shape[1] + [0.002]), method='L-BFGS-B', bounds=[(-4, 1)] * x.shape[1] + [(-12, -1)], options={'maxiter': 70}).x
    return _predict(p, pt, kernel(delta, par), kernel(delta_test, par), y, np.exp(par[-1]))

def _relaxation(traj, t, initial):
    from scipy.optimize import least_squares

    def basis(rates):
        return -np.expm1(-t[:, None] * rates)

    def residual(rates):
        b = basis(rates)
        return (b @ _fit(b, traj.T) - traj.T).ravel()
    rates = least_squares(residual, initial, bounds=([0.7, 0.05], [4.0, 0.65])).x
    modes = np.linalg.qr(basis(rates), mode='reduced')[0]
    return (traj @ modes, modes)
